const suppliedPacks = {
  ...(globalThis.ABBATE_I18N_PACKS||{}),
  ru: globalThis.ABBATE_I18N_RU,
  uk: globalThis.ABBATE_I18N_UK
};
const modernCopy = globalThis.ABBATE_I18N_MODERN||{};
const modernExact = new Map();
for (const [source, translated] of Object.entries(modernCopy)) modernExact.set(source,translated);

const repairPack = (code,pack) => pack.map((value,index)=>{
  let repaired=String(value);
  const variables=[...ABBATE_SOURCE[index].matchAll(/\{([a-z]+)\}/gi)].map(match=>match[1]);
  for(const name of variables){
    if(new RegExp(`\\{${name}\\}`,'i').test(repaired))continue;
    if(code==='pl'&&index===100&&name==='count')repaired=repaired.replace('na przykładowe pytania','na {count} przykładowe pytania');
    else repaired=`{${name}} ${repaired}`;
  }
  return repaired;
});
const packs = new Map([['de',ABBATE_SOURCE],...Object.entries(suppliedPacks).map(([code,pack])=>[code,repairPack(code,pack)])]);
const textSources = new WeakMap();
const attributeSources = new WeakMap();
let activeCode = 'de';
let activePack = ABBATE_SOURCE;

const templateMatchers=ABBATE_SOURCE.map((source,index)=>{
  if(!/\{[a-z]+\}/i.test(source))return null;
  const names=[];
  const escaped=source.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const pattern=escaped.replace(/\\\{([a-z]+)\\\}/gi,(_,name)=>{names.push(name);return '(.+?)';});
  return {index,names,regex:new RegExp(`^${pattern}$`)};
}).filter(Boolean);

const exactIndex=new Map(ABBATE_SOURCE.map((value,index)=>[value,index]));

function format(value,variables={}){
  return String(value).replace(/\{([a-z]+)\}/gi,(_,name)=>variables[name]??`{${name}}`);
}

function translateText(value){
  const original=String(value),trimmed=original.trim();
  if(!trimmed)return original;
  let translated,staticIndex=exactIndex.get(trimmed);
  if(staticIndex!==undefined)translated=activePack[staticIndex];
  else{
    for(const matcher of templateMatchers){
      const match=trimmed.match(matcher.regex);
      if(!match)continue;
      const variables={};matcher.names.forEach((name,index)=>{variables[name]=match[index+1];});
      translated=format(activePack[matcher.index],variables);break;
    }
  }
  // Current production UI contains new course names and learning copy that are
  // not in the legacy demo catalogue. Translate them via the small modern layer.
  if(!translated && activeCode!=='de'){
    const translations=modernExact.get(trimmed);
    if(translations)translated=translations[activeCode];
  }
  if(!translated)return original;
  return original.slice(0,original.indexOf(trimmed))+translated+original.slice(original.indexOf(trimmed)+trimmed.length);
}

function localize(root=document.body){
  if(!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  let node;
  while((node=walker.nextNode())){
    if(!textSources.has(node))textSources.set(node,node.nodeValue);
    node.nodeValue=translateText(textSources.get(node));
  }
  const elements=root.querySelectorAll?.('[aria-label],[alt],[placeholder],[title]')||[];
  for(const element of elements){
    if(!attributeSources.has(element))attributeSources.set(element,{});
    const sources=attributeSources.get(element);
    for(const attribute of ['aria-label','alt','placeholder','title']){
      if(!element.hasAttribute(attribute))continue;
      if(!(attribute in sources))sources[attribute]=element.getAttribute(attribute);
      element.setAttribute(attribute,translateText(sources[attribute]));
    }
  }
}

function syncCopy(code,pack){
  api.copy[code]={home:pack[0],learn:pack[1],exam:pack[2],results:pack[3],title:pack[4],intro:pack[5],change:pack[6],selected:pack[7],readyTitle:pack[180]||pack[7],readyBody:pack[8]};
}

async function load(code){
  if(!ABBATE_LANGUAGES.some(language=>language.code===code))code='de';
  const pack=packs.get(code);
  if(!Array.isArray(pack)||pack.length!==ABBATE_SOURCE.length||pack.some(value=>!value))throw new Error(`Incomplete translation pack: ${code}`);
  packs.set(code,pack);activeCode=code;activePack=pack;syncCopy(code,pack);return pack;
}

const api={
  languages:ABBATE_LANGUAGES,
  shellLabels:ABBATE_SHELL_LABELS,
  copy:{},
  load,
  localize,
  text:translateText,
  t(index,variables){return format(activePack[index]||ABBATE_SOURCE[index]||'',variables);},
  get code(){return activeCode;},
  get sourceCount(){return ABBATE_SOURCE.length;}
};

syncCopy('de',ABBATE_SOURCE);
globalThis.ABBATE_I18N=Object.freeze(api);
